-- Read-only checks; no athlete data is modified.
select 'Deletion timestamp column' as check_name,count(*)::text as actual,'1' as expected from information_schema.columns where table_schema='public' and table_name='training_sessions' and column_name='deleted_at'
union all select 'Authenticated delete and Undo functions',count(*)::text,'2' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('delete_training_session','restore_training_session') and p.prosecdef and has_function_privilege('authenticated',p.oid,'execute')
union all select 'Anonymous delete or Undo access',count(*)::text,'0' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('delete_training_session','restore_training_session') and has_function_privilege('anon',p.oid,'execute')
union all select 'Session writers exclude deleted rows',count(*)::text,'3' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('save_training_session_internal','complete_training_session_internal','save_workout_section') and lower(p.prosrc) like '%deleted_at is null for update%'
union all select 'Read policy hides deleted sessions',count(*)::text,'1' from pg_policies where schemaname='public' and tablename='training_sessions' and policyname='training_sessions_read' and lower(qual) like '%deleted_at is null%'
union all select 'Temporary deletion test accounts',count(*)::text,'0' from auth.users where id in ('00000000-0000-4000-8000-000000000051','00000000-0000-4000-8000-000000000052')
union all select 'Completed and logged deletion guard',count(*)::text,'1' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='delete_training_session' and p.prosrc like '%row_session.status=''completed'' or exists(select 1 from public.workout_results where session_id=row_session.id)%';
